class BinaryTreeUtil {
  static stringify = (root) => {
    const maxLevel = BinaryTreeUtil.maxLevel(root);
    const buffer = [];
    BinaryTreeUtil._stringify([root], 1, maxLevel, buffer);
    return buffer.join("");
  };

  static _stringify = (nodes, level, maxLevel, buffer) => {
    if (nodes.length === 0 || nodes.every((node) => node === null)) return;

    const height = maxLevel - level;
    const edgeLines = Math.pow(2, Math.max(height - 1, 0));
    const leftSpaces = Math.pow(2, height) - 1;
    const betweenSpaces = Math.pow(2, height + 1) - 1;
    buffer.push(BinaryTreeUtil.getWhitespaces(leftSpaces));

    const newNodes = [];
    for (let node of nodes) {
      if (node !== null) {
        buffer.push(node.val);
        newNodes.push(node.left);
        newNodes.push(node.right);
      } else {
        buffer.push(" ");
        newNodes.push(null);
        newNodes.push(null);
      }
      buffer.push(BinaryTreeUtil.getWhitespaces(betweenSpaces));
    }

    buffer.push("\n");

    for (let i = 1; i <= edgeLines; i += 1) {
      for (let j = 0; j < nodes.length; j += 1) {
        buffer.push(BinaryTreeUtil.getWhitespaces(leftSpaces - i));
        if (nodes[j] === null) {
          buffer.push(
            BinaryTreeUtil.getWhitespaces(edgeLines + edgeLines + i + 1)
          );
          continue;
        }

        if (nodes[j].left !== null) {
          buffer.push("/");
        } else {
          buffer.push(BinaryTreeUtil.getWhitespaces(1));
        }

        buffer.push(BinaryTreeUtil.getWhitespaces(i + i - 1));

        if (nodes[j].right !== null) {
          buffer.push("\\");
        } else {
          buffer.push(BinaryTreeUtil.getWhitespaces(1));
        }

        buffer.push(BinaryTreeUtil.getWhitespaces(edgeLines + edgeLines - i));
      }

      buffer.push("\n");
    }

    BinaryTreeUtil._stringify(newNodes, level + 1, maxLevel, buffer);
  };

  static stringFromLevels = (levels) => {
    const buffer = [];
    const maxLevel = levels.length;
    for (let l = 0; l < levels.length; l += 1) {
      const level = l + 1;
      const height = maxLevel - level;
      const edgeLines = Math.pow(2, Math.max(height - 1, 0));
      const leftSpaces = Math.pow(2, height) - 1;
      const betweenSpaces = Math.pow(2, height + 1) - 1;
      buffer.push(BinaryTreeUtil.getWhitespaces(leftSpaces));

      const nodes = levels[l];

      for (let node of nodes) {
        if (node !== null) {
          buffer.push(node);
        } else {
          buffer.push(" ");
        }
        buffer.push(BinaryTreeUtil.getWhitespaces(betweenSpaces));
      }
      buffer.push("\n");

      for (let i = 1; i <= edgeLines; i += 1) {
        for (let j = 0; j < nodes.length; j += 1) {
          buffer.push(BinaryTreeUtil.getWhitespaces(leftSpaces - i));
          if (nodes[j] === null) {
            buffer.push(
              BinaryTreeUtil.getWhitespaces(edgeLines + edgeLines + i + 1)
            );
            continue;
          }

          if (l === levels.length - 1 || levels[l + 1][2 * j] === null) {
            buffer.push(BinaryTreeUtil.getWhitespaces(1));
          } else {
            buffer.push("/");
          }

          buffer.push(BinaryTreeUtil.getWhitespaces(i + i - 1));

          if (l === levels.length - 1 || levels[l + 1][2 * j + 1] === null) {
            buffer.push(BinaryTreeUtil.getWhitespaces(1));
          } else {
            buffer.push("\\");
          }

          buffer.push(BinaryTreeUtil.getWhitespaces(edgeLines + edgeLines - i));
        }

        buffer.push("\n");
      }
    }

    return buffer.join("");
  };

  static getWhitespaces = (count) => {
    const buffer = [];
    for (let i = 0; i < count; i += 1) buffer.push(" ");
    return buffer.join("");
  };

  static maxLevel = (root) => {
    if (root === null) return 0;
    return (
      1 +
      Math.max(
        BinaryTreeUtil.maxLevel(root.left),
        BinaryTreeUtil.maxLevel(root.right)
      )
    );
  };
}

