## solution

#### recursive with vector copies

```cpp
#include <vector>
#include <algorithm>
#include <string>

Node* buildTreeInPre(std::vector<std::string> inorder, std::vector<std::string> preorder) {
  if (inorder.size() == 0) {
    return nullptr;
  }

  std::string val = preorder[0];
  Node* root = new Node(val);
  auto p = std::find(inorder.begin(), inorder.end(), val);
  std::vector<std::string> leftIn(inorder.begin(), p);
  std::vector<std::string> rightIn(p + 1, inorder.end());
  std::vector<std::string> leftPre(preorder.begin() + 1, preorder.begin() + 1 + leftIn.size());
  std::vector<std::string> rightPre(preorder.begin() + 1 + leftIn.size(), preorder.end());

  root->left = buildTreeInPre(leftIn, leftPre);
  root->right = buildTreeInPre(rightIn, rightPre);
  return root;
}
```

- n = length of array
- Time: O(n^2)
- Space: O(n^2)

#### recursive in-place

```cpp
#include <vector>
#include <algorithm>
#include <string>

Node* buildTreeInPre(std::vector<std::string> inorder, std::vector<std::string> preorder, int startIn, int endIn, int startPre, int endPre) {
  if (endIn < startIn) {
    return nullptr;
  }

  std::string val = preorder[startPre];

  Node* root = new Node(val);
  int mid = std::find(inorder.begin(), inorder.end(), val) - inorder.begin();
  int size = (mid - startIn);
  root->left = buildTreeInPre(inorder, preorder, startIn, mid - 1, startPre + 1, startPre + size);
  root->right = buildTreeInPre(inorder, preorder, mid + 1, endIn, startPre + 1 + size, endPre);

  return root;
}

Node* buildTreeInPre(std::vector<std::string> inorder, std::vector<std::string> preorder) {
  return buildTreeInPre(inorder, preorder, 0, inorder.size() - 1, 0, preorder.size() - 1);
}
```

- n = length of array
- Time: O(n)
- Space: O(n)
